/** Pattern ids that fire (always horizontal) lasers. */
export const LASER_PATTERNS = new Set(['laser', 'pulse', 'longlaser', 'twinlaser', 'trilaser', 'sweep']);

/** Fallback loadouts by tier for any unknown (non-wave) id. */
export const TIER_ATTACKS = {
  basic: { iv: 1.9,  seq: [['single'], ['laser', { spd: 400 }]] },
  swarm: { iv: 2.0,  seq: [['single', { spd: 170 }]] },
  drone: { iv: 1.8,  seq: [['laser', { spd: 440 }], ['missile', { home: 0.4 }]] },
  elite: { iv: 1.5,  seq: [['spread3'], ['laser', { spd: 500 }]] },
  tank:  { iv: 1.1,  seq: [['laser', { spd: 510 }], ['spread3', { spd: 185 }], ['missile', { home: 0.48 }]] },
  mech:  { iv: 1.3,  seq: [['twinlaser'], ['missile', { home: 0.6 }]] },
  golem: { iv: 1.2,  seq: [['trilaser'], ['missile', { home: 0.45 }]] },
  boss:  { iv: 1.0,  seq: [['longlaser'], ['fan5', { n: 7, a: 0.18 }], ['salvo', { n: 3 }]] },
};

/** Loadout for a catalog / unknown kind id (tier fallback). Wave kinds are handled by the caller. */
export function unitAttackLoadout(id, tier) {
  if (UNIT_ATTACKS[id]) return UNIT_ATTACKS[id];
  const u = CATALOG_BY_ID[id];
  const t = tier || (u && u.tier) || 'basic';
  return TIER_ATTACKS[t] || TIER_ATTACKS.basic;
}

/** Unique pattern ids of a loadout, in signature-first order. */
export function loadoutPatternIds(lo) {
  const out = [];
  for (const [pid] of (lo && lo.seq) || []) if (!out.includes(pid)) out.push(pid);
  return out;
}

/**
 * Ids removed when the sprite sheet was replaced (v1.5.59) → closest new unit,
 * so previously purchased units stay owned / equipped.
 */
export const LEGACY_ID_MAP = {
  mk3_interceptor: 'scout_drone',
  mini_hinobunni: 'gunship_alpha_b',
  ionregon: 'fighter_mk2',
  security_fly: 'drone_swarm_node_variant',
  missile_cruiser: 'missile_destroyer',
  strike_fighter: 'cruiser_class',
  strike_fighter_b: 'destroyer_class',
  security_eye: 'combat_walker',
  engineer_bot: 'assault_transport',
  emp_disruptor: 'siege_mech',
};

export function unitIntro(id) {
  const u = CATALOG_BY_ID[id];
  const tier = (u && u.tier) || 'basic';
  const base = TIER_INTRO[tier] || TIER_INTRO.basic;
  const ov = UNIT_INTRO_OVERRIDES[id] || {};
  const pids = loadoutPatternIds(unitAttackLoadout(id, tier));
  const names = pids.map((p) => (ATTACK_PATTERN_INFO[p] && ATTACK_PATTERN_INFO[p].ja) || p);
  const sig = ATTACK_PATTERN_INFO[pids[0]];
  const rest = names.slice(1);
  const hasLaser = pids.some((p) => LASER_PATTERNS.has(p));
  // Large tiers only telegraph lasers — drop the note for units without any laser pattern.
  const role = hasLaser ? base.role : base.role.replace('・予告レーザー', '');
  const blurb = `${ov.lead || base.lead}${sig ? sig.desc : ''}${rest.length ? `${rest.join('・')}も織り交ぜる。` : ''}`;
  return {
    id,
    name: (u && u.name) || id,
    tier,
    rarity: (u && u.rarity) || 'common',
    attack: ov.attack || names.join('／') || base.attack,
    role: ov.role || role,
    blurb: ov.blurb || blurb,
  };
}

